# Normal function (Uses lots of memory)
def square_numbers_list(nums):
    result = []
    for i in nums:
        result.append(i*i)
    return result

# Generator function (Uses almost zero memory)
def square_numbers_generator(nums):
    for i in nums:
        yield i*i

# Using the generator
my_nums = square_numbers_generator([1, 2, 3, 4, 5])
for num in my_nums:
    print(num)

