def my_logger(original_function):
    def wrapper(*args, **kwargs):
        print(f"LOG: {original_function.__name__} started.")
        result = original_function(*args, **kwargs)
        print(f"LOG: {original_function.__name__} finished.")
        return result
    return wrapper

@my_logger
def display_info(name, age):
    print(f"Info ran with arguments ({name}, {age})")

display_info("Alice", 25)

