import json
import os

FILE_NAME = "tasks.json"

def load_tasks():
    if not os.path.exists(FILE_NAME):
        return []
    with open(FILE_NAME, 'r') as file:
        return json.load(file)

# Skeleton for the main loop
def main():
    tasks = load_tasks()
    while True:
        print("\n1. View 2. Exit")
        choice = input("Choice: ")
        if choice == '2':
            print("Goodbye!")
            break
        elif choice == '1':
            print(f"You have {len(tasks)} tasks.")

if __name__ == "__main__":
    main()
